"""Optional static visual design preview (not the deployed Streamlit app)."""
from pathlib import Path
from html import escape
import sys
import numpy as np
sys.path.insert(0,str(Path(__file__).resolve().parent))
from analysis import ROOT, prepare_data, load_raw

raw = load_raw()
df,_=prepare_data(raw)
colors={'Action':'#146F79','Comedy':'#8CA6B8','Drama':'#325270','Horror':'#B5C5D1'}
xs=115 + 830*df.metascore/100
logg=np.log10(df.gross_worldwide)
lo=max(3.5,float(logg.min()));hi=max(lo+1,float(logg.max()))
ys=330-275*(logg-lo)/(hi-lo)
points=[]
for x,y,(_,r) in zip(xs,ys,df.iterrows()):
 title=escape(str(r.title),quote=True)
 points.append(f'<circle class="dot" data-genre="{r.primary_genre}" cx="{float(x):.1f}" cy="{float(y):.1f}" r="4.0" fill="{colors[r.primary_genre]}" opacity="0.7"><title>{title} · Metascore {int(r.metascore)} · ${r.gross_worldwide/1e6:,.1f}M</title></circle>')

def escape_svg_content(s):return s

html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Beyond the Ratings — design preview</title><style>
*{box-sizing:border-box}body{margin:0;background:#F7FAFD;color:#173049;font-family:Inter,Arial,sans-serif;font-size:15px}aside{position:fixed;top:0;bottom:0;left:0;width:239px;background:#EDF3F8;border-right:1px solid #DDE8EF;padding:28px 22px}aside strong{font-size:16px;letter-spacing:.03em}aside .sm{color:#748799;font-size:12px;margin-top:6px}nav{display:grid;gap:18px;margin-top:40px}nav a{color:#536D84;text-decoration:none;font-size:13px}nav a:hover{color:#146F79}main{margin:0 20px 0 259px;max-width:1260px;padding:22px 17px 120px}.hero{background:linear-gradient(120deg,#102841 0%,#1D445C 70%,#176D75 150%);padding:45px 50px;border-radius:20px;color:white;box-shadow:0 11px 31px rgba(25,45,66,.1)}.eyebrow{font-size:11px;letter-spacing:2.4px;text-transform:uppercase;color:#99D1D3;font-weight:750}.hero h1{font-size:62px;letter-spacing:-2px;line-height:1.05;margin:16px 0}.hero p{color:#D6E5ED;line-height:1.6;font-size:16px;max-width:720px}.tags{display:flex;gap:10px;margin-top:30px}.tag{background:#355A6E;border:1px solid #497285;color:#E9F4F6;padding:10px 12px;border-radius:28px;font-size:12px}.section{margin-top:53px}.section .eyebrow{color:#147A80}.section h2{font-size:33px;letter-spacing:-1px;margin:8px 0 12px}.section p{color:#62778A;max-width:800px;line-height:1.6}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:26px 0}.stat{background:#fff;border:1px solid #DFE9F0;padding:22px 18px;border-radius:16px}.stat label{display:block;font-weight:bold;color:#658093;letter-spacing:1px;font-size:11px}.stat strong{font-size:33px;display:block;margin:8px 0}.stat small{color:#7D8E9C}.chart{background:white;border:1px solid #DAE6EE;border-radius:16px;padding:22px 28px}.chart h3{margin:0 0 10px}.row{display:flex;gap:18px;align-items:center}.row span{margin-left:auto;color:#6C8092;font-size:12px}select{border:1px solid #D5E3EA;border-radius:8px;padding:8px;color:#17354B;background:#F5F9FA}svg{width:100%;height:auto}.plotline{stroke:#D9E4EB;stroke-width:1;fill:none}.axislabel{fill:#7D8F9C;font-size:10px}.caps{color:#7E8D9B;font-size:11px;margin-top:5px}.callout{background:#EAF5F3;padding:24px 30px;border-radius:14px;border-left:4px solid #147A80;margin-top:24px}.callout b{color:#1D535B}.muted-banner{background:#DFEAEF;color:#45677D;border-radius:8px;padding:10px 13px;margin:16px 0;font-size:12px}#map-mini{width:100%;max-width:850px;border-radius:12px;margin-top:18px}.footer{margin-top:70px;color:#7C8FA0;font-size:11px;letter-spacing:1.5px;text-align:center}@media(max-width:850px){aside{display:none}main{margin:0 8px}.hero h1{font-size:39px}.stats{grid-template-columns:repeat(2,1fr)}}
</style></head><body><aside><strong>🎞️ BEYOND THE RATINGS</strong><div class="sm">ACDT Project 1 · Story preview</div><nav><a href="#myth">01 · The myth</a><a href="#data">02 · The data</a><a href="#reversal">03 · The reversal</a><a href="#maps">04 · System maps</a><a href="#end">05 · Next steps</a></nav><p class="sm" style="margin-top:60px">This is a static visual preview. The full Streamlit app includes 8 chapters, live fitted calculations, all three maps and download buttons.</p></aside><main><section class="hero"><div class="eyebrow">An interactive ACDT data story · project 1</div><h1>Beyond the Ratings.</h1><p>Do better-reviewed films earn more? A journey from a familiar assumption to the hidden systems shaping global box-office success.</p><div class="tags"><div class="tag">2022–2025 releases</div><div class="tag">385 films analyzed</div><div class="tag">4 genres</div><div class="tag">Regression + RF + DML</div></div></section><div class="muted-banner">DESIGN PREVIEW · Main live site is implemented in app.py and must be run with Streamlit.</div><section class="section" id="myth"><div class="eyebrow">Chapter 01</div><h2>The myth: a better review means a bigger hit</h2><p>Higher Metascores are often thought to translate into higher worldwide box office. We tested that assumption while considering budget, release year and genre.</p><div class="callout"><b>Research question:</b> How does Metacritic Metascore relate to worldwide gross after adjustment — and does genre change the association?</div></section><section class="section" id="data"><div class="eyebrow">Chapter 02</div><h2>Meet the evidence</h2><p>Every dot is a movie. The real scatter below uses all 385 study movies and retains the log-scaled revenue axis.</p><div class="stats"><div class="stat"><label>INPUT FILMS</label><strong>407</strong><small>USD-converted candidates</small></div><div class="stat"><label>VALIDATED</label><strong>406</strong><small>After model checks</small></div><div class="stat"><label>STUDY SAMPLE</label><strong>385</strong><small>Across four target genres</small></div><div class="stat"><label>RANGE</label><strong>2022–25</strong><small>2025 partially covered</small></div></div><div class="chart"><div class="row"><h3>Metascore vs worldwide gross</h3><span>Choose a genre to explore</span><select id="genre" onchange="filterGenre(this.value)"><option value="All">All genres</option><option>Action</option><option>Comedy</option><option>Drama</option><option>Horror</option></select></div><svg viewBox="0 0 1000 388" aria-label="Scatterplot of Metascore and logarithmic worldwide gross"><path class="plotline" d="M115 50V330H960"/><path class="plotline" d="M115 120H960 M115 190H960 M115 260H960"/><g id="movie-dots">''' + '\n'.join(points) + '''</g><text class="axislabel" x="510" y="370">Critic Metascore (0–100)</text><text class="axislabel" transform="translate(20 255) rotate(-90)">Worldwide gross (log USD)</text></svg><div class="caps">Hover points for exact movie names and values. Preview filters only; the live site includes a year slider and fitted confidence intervals.</div></div></section><section class="section" id="reversal"><div class="eyebrow">Chapter 03</div><h2>The reversal: adjustment changes the story</h2><div class="stats" style="grid-template-columns:repeat(2,1fr)"><div class="stat"><label>SIMPLE REGRESSION</label><strong>−9.1%</strong><small>p = 0.205 · not significant</small></div><div class="stat"><label>MULTIPLE REGRESSION</label><strong style="color:#147A80">+22.9%</strong><small>p = 0.0008 · conditional on modeled controls</small></div></div><div class="callout">Prediction, association and causation are different. The full site explains this distinction in each model and system map.</div></section><section class="section" id="maps"><div class="eyebrow">Chapter 06</div><h2>Three ways to see one system</h2><p>Map A: statistical associations · Map B: theoretical hidden factors · Map C: machine-learning interpretation.</p><img id="map-mini" src="assets/map_b.png" alt="System map B preview"></section><div class="footer" id="end">ACDT PROJECT 1 · FULL INTERACTIVE SITE: STREAMLIT / app.py</div></main><script>function filterGenre(g){document.querySelectorAll('#movie-dots .dot').forEach(function(e){e.style.display=(g==='All'||e.getAttribute('data-genre')===g)?'':'none'})}</script></body></html>'''
(ROOT/'design_preview.html').write_text(html,encoding='utf-8')
print('design_preview.html',len(html), 'bytes')
